package main

import (
	"fmt"
	"io"
	"slices"
	"strings"

	"github.com/spf13/cobra"

	"github.com/ianglennon/tierplan/internal/rbac"
)

const (
	formatMarkdown   = "markdown"
	formatTypeScript = "typescript"

	// generatedBy is the marker that exempts a generated file from the SPDX gate
	// and from editing by hand.
	generatedBy = "Code generated by tierplan permissions; DO NOT EDIT."
)

// newPermissionsCmd prints the role to permission matrix from the Go registry,
// the only place roles are defined (D-15b). `make gen` writes docs/permissions.md
// and web/src/api/permissions.gen.ts from it, and `make gen-check` fails when
// either drifts.
func newPermissionsCmd() *cobra.Command {
	var format string
	cmd := &cobra.Command{
		Use:   "permissions",
		Short: "Print the role to permission matrix from the permission registry",
		Long: "Prints what each environment role may do, generated from the permission registry so the documentation and the\n" +
			"web interface cannot drift from the server. Formats: " + formatMarkdown + " (docs/permissions.md) and " +
			formatTypeScript + " (web/src/api/permissions.gen.ts).",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			rows := rbac.MatrixRows(rbac.DefaultRegistry())
			switch format {
			case formatMarkdown:
				return writePermissionsMarkdown(cmd.OutOrStdout(), rows)
			case formatTypeScript:
				return writePermissionsTypeScript(cmd.OutOrStdout(), rows)
			}
			return fmt.Errorf("unknown --format %q: use %s or %s", format, formatMarkdown, formatTypeScript)
		},
	}
	cmd.Flags().StringVar(&format, "format", formatMarkdown, "output format: "+formatMarkdown+" or "+formatTypeScript)
	return cmd
}

// yesNo is a matrix cell.
func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

// operatorCell is "extra" for a permission an Operator holds only when the
// assignment carries it (D-16, D-17).
func operatorCell(r rbac.MatrixRow) string {
	if r.Extra {
		return "extra"
	}
	return yesNo(r.Operator)
}

func writePermissionsMarkdown(w io.Writer, rows []rbac.MatrixRow) error {
	var b strings.Builder
	b.WriteString("<!-- " + generatedBy + " -->\n")
	b.WriteString("<!-- SPDX-License-Identifier: AGPL-3.0-or-later -->\n")
	b.WriteString("<!-- SPDX-FileCopyrightText: 2026 The TierPlan Authors -->\n\n")
	b.WriteString("# Roles and permissions\n\n")
	b.WriteString("This page is generated from the permission registry in `internal/rbac/permissions.go` by `make gen`. " +
		"There is no roles page in the web interface: the three roles are fixed, and this is where they are written down.\n\n")
	b.WriteString("## How access is worked out\n\n")
	b.WriteString("- **Roles are per environment.** Viewer, Operator and Admin apply inside one environment, or inside every environment " +
		"when the assignment is made for all environments. A higher role holds everything a lower one does.\n")
	b.WriteString("- **Grants are a union (D-06).** A user's access to an environment is the union of the grants made to them, " +
		"to the teams they belong to, and to all environments. The highest role wins, the extras of every grant add up, and there are no deny rules. " +
		"The user's page shows where each environment's access comes from.\n")
	b.WriteString("- **Extras are held by Operators only when granted (D-16, D-17).** The dangerous permissions marked `extra` below " +
		"belong to an Admin always, to an Operator only when the assignment carries them, and to a Viewer never.\n")
	b.WriteString("- **Changing a service exposes what it holds (D-13 amended).** `services.control` lets an Operator change what a service runs, " +
		"so they can read the values withheld from them on the services they edit (environment values, command line, health check and log options) " +
		"and the secrets those services already use, even without `secrets.reveal`. Adding a secret a service does not already use, " +
		"or rolling back to a version that uses one, needs `secrets.reveal`. See residual risk 36 in docs/threat-model.md.\n")
	b.WriteString("- **The instance admin is a flag on a user, not a role (D-01, D-03).** An instance admin holds Admin on every environment " +
		"with every extra, and is the only holder of the global permissions. Environment roles never grant a global permission.\n")
	b.WriteString("- **Delegation is capped (D-12).** An environment Admin can assign Admin, Operator or Viewer, and the extras, on the " +
		"environments they administer. They cannot grant all-environments scope or instance admin.\n\n")
	b.WriteString("## Matrix\n\n")
	b.WriteString("`extra` means an Operator holds the permission only when the assignment carries it. A global permission is held by instance admins alone.\n\n")
	b.WriteString("| Permission | Scope | Viewer | Operator | Admin | Instance admin | Dangerous | Description |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- |\n")
	for _, r := range rows {
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | yes | %s | %s |\n",
			r.Name, r.Scope, yesNo(r.Viewer), operatorCell(r), yesNo(r.Admin), yesNo(r.Dangerous), r.Description)
	}
	_, err := io.WriteString(w, b.String())
	return err
}

// tsList writes a readonly array of permission names.
func tsList(b *strings.Builder, name, doc string, names []string) {
	b.WriteString("// " + doc + "\n")
	b.WriteString("export const " + name + " = [\n")
	for _, n := range names {
		fmt.Fprintf(b, "  %q,\n", n)
	}
	b.WriteString("] as const;\n\n")
}

func writePermissionsTypeScript(w io.Writer, rows []rbac.MatrixRow) error {
	var global, env, extra, dangerous []string
	for _, r := range rows {
		if r.Scope == "global" {
			global = append(global, r.Name)
		} else {
			env = append(env, r.Name)
		}
		if r.Extra {
			extra = append(extra, r.Name)
		}
		if r.Dangerous {
			dangerous = append(dangerous, r.Name)
		}
	}
	// The rows are already in name order; keep each list that way.
	for _, l := range [][]string{global, env, extra, dangerous} {
		if !slices.IsSorted(l) {
			return fmt.Errorf("permissions: rows are not sorted by name")
		}
	}

	var b strings.Builder
	b.WriteString("// " + generatedBy + "\n")
	b.WriteString("// Source: the permission registry in internal/rbac/permissions.go. Run `make gen` after changing it.\n\n")
	tsList(&b, "GLOBAL_PERMISSIONS", "Permissions held by instance admins alone.", global)
	tsList(&b, "ENVIRONMENT_PERMISSIONS", "Permissions checked against one environment.", env)
	tsList(&b, "EXTRA_PERMISSIONS", "Environment permissions an Operator holds only when the assignment carries them.", extra)
	tsList(&b, "DANGEROUS_PERMISSIONS", "Permissions the access screens mark as dangerous.", dangerous)
	b.WriteString("export type PermissionName =\n  | (typeof GLOBAL_PERMISSIONS)[number]\n  | (typeof ENVIRONMENT_PERMISSIONS)[number];\n\n")
	b.WriteString("// What a permission asks of a caller: a role and above, an extra grant on top of Operator, or instance admin.\n")
	b.WriteString("export interface PermissionRequirement {\n  kind: \"role\" | \"extra\" | \"instance\";\n  role?: \"viewer\" | \"operator\" | \"admin\";\n}\n\n")
	b.WriteString("export const PERMISSION_REQUIREMENTS: Record<PermissionName, PermissionRequirement> = {\n")
	for _, r := range rows {
		switch r.Need.Kind {
		case rbac.NeedInstance:
			fmt.Fprintf(&b, "  %q: { kind: %q },\n", r.Name, string(r.Need.Kind))
		default:
			fmt.Fprintf(&b, "  %q: { kind: %q, role: %q },\n", r.Name, string(r.Need.Kind), r.Need.Role.String())
		}
	}
	b.WriteString("};\n")
	_, err := io.WriteString(w, b.String())
	return err
}
